{
  "title": "The Mirror's Edge Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "Arrival at the ruined city gates.",
      "visual_description": "Massive iron gates twisted and rusted, with old royal banners hanging in tatters above. The glass diver stands at the entrance, his helmet reflecting the shattered city beyond.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 2,
      "caption": "Mara unrolls her map by torchlight.",
      "visual_description": "Mara the Cartographer kneels on cobblestones, spreading a stained parchment map across her knees. Her brass compass glints under the guttering flame of a nearby lamp.",
      "characters": ["mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 3,
      "caption": "The Oracle Lamp flickers a warning.",
      "visual_description": "The Oracle Lamp sits on a broken wall, its one-eyed flame casting long shadows. The flame pulses orange as it speaks, reflecting in the glass diver's helmet.",
      "characters": ["oracle_lamp", "glass_diver"]
    },
    {
      "scene_number": 4,
      "caption": "Tin Fox scouts the cursed tower.",
      "visual_description": "The small metal fox darts between rubble, its key-wind tail spinning. Blue glass eyes scan the base of a leaning tower wrapped in thorny vines.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 5,
      "caption": "The sleeping tax collector blocks the path.",
      "visual_description": "A ledger book serves as a pillow, stamped papers stuck to the sleeping official's sleeves. He snores softly on the only passable step, a brass inkwell beside him.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 6,
      "caption": "Mara navigates through a collapsed market.",
      "visual_description": "Mara steps over toppled stalls and scattered fruit crates, compass held high. The glass diver follows, his coat reflecting the faded colors of old banners.",
      "characters": ["mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 7,
      "caption": "The Oracle Lamp reveals a false door.",
      "visual_description": "The lamp's flame brightens, illuminating a stone door carved with no handle. Its eye stares at the seams as if reading invisible runes.",
      "characters": ["oracle_lamp", "glass_diver"]
    },
    {
      "scene_number": 8,
      "caption": "Tin Fox finds a hidden mechanism.",
      "visual_description": "The metal fox noses at a loose cobblestone, then presses a paw down. A grinding sound echoes from the false door, which begins to slide sideways.",
      "characters": ["tin_fox", "glass_diver"]
    },
    {
      "scene_number": 9,
      "caption": "Mara recalculates the route.",
      "visual_description": "Mara marks a new path on her map with a charcoal stick, her tired eyes scanning the towers. The glass diver peers over her shoulder, helmet catching moonlight.",
      "characters": ["mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 10,
      "caption": "Armored patrols march through a square.",
      "visual_description": "A column of figures in plate armor clanks across a plaza, their helmets hiding all faces. The glass diver ducks behind a fallen pillar, waiting.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 11,
      "caption": "The sleeping tax collector stirs but doesn't wake.",
      "visual_description": "The official shifts on his ledger pillow, muttering numbers in his sleep. Stamped papers flutter as he turns over, blocking another path.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 12,
      "caption": "Oracle Lamp warns of a trap ahead.",
      "visual_description": "The lamp's flame turns blue, casting cold light across a corridor. Cracks in the floor hint at a pitfall, and the one-eyed flame shakes side to side.",
      "characters": ["oracle_lamp", "glass_diver"]
    },
    {
      "scene_number": 13,
      "caption": "Tin Fox triggers a false alarm.",
      "visual_description": "The metal fox steps on a pressure plate, causing a bell to ring in a distant tower. Armored footsteps grow louder, and the group hides in a shadowy alcove.",
      "characters": ["tin_fox", "glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 14,
      "caption": "Mara spots the bridge in the distance.",
      "visual_description": "From a broken window, Mara points to a long stone bridge spanning a dry riverbed. The bridge is guarded by a single armored figure at the far end.",
      "characters": ["mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 15,
      "caption": "The glass diver swims through a window reflection.",
      "visual_description": "The glass diver touches a cracked window pane, and his body dissolves into the glass, re-emerging inside a locked tower room. Shards of light dance around him.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 16,
      "caption": "Oracle Lamp guides the final passage.",
      "visual_description": "The lamp's flame burns steady as it floats ahead, lighting a narrow alley leading toward the bridge. Shadows retreat from its glow.",
      "characters": ["oracle_lamp", "mara_the_cartographer", "tin_fox", "glass_diver"]
    },
    {
      "scene_number": 17,
      "caption": "The escape across the bridge begins.",
      "visual_description": "The group rushes onto the stone bridge, the armored figure at the far end turning toward them. The glass diver's coat trails like a banner in the wind.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 18,
      "caption": "The bridge crumbles but the rescue succeeds.",
      "visual_description": "The bridge cracks behind them as they reach the far side. The armored figure halts at the gap, and the exhausted group collapses on safe ground, the lamp flickering triumphantly.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox"]
    }
  ]
}

